\label{rjs} 
If $\alpha = \epsilon_i-\delta_{j}$, the following are equivalent
                                                      
\begin{itemize} \item[{{\rm$($a$)$}}] $ \mathfrak{B}(\alpha)$ is an inner corner  of $\lambda$, that is $\lambda\in X_{-\alpha}$.
                                                                                                                                          
\item[{{\rm$($b$)$}}] $\lambda_{n+1-i} = j$                     
and $\lambda'_{j} = n+1-i$ .
\end{itemize}
If these conditions hold then 
\begin{equation} \label{qef}  t_{-\alpha}(\lambda) = (\lambda_1,\ldots , \lambda_{n-i}, \lambda_{n+1-i}-1,\lambda_{n+2-i},\ldots, \lambda_n).\nonumber\end{equation}

\label{rjx} 
If $\alpha = \epsilon_i-\delta_{j}$, the following are equivalent
                                                      
\begin{itemize} \item[{{\rm$($a$)$}}] $ \mathfrak{B}(\alpha)$ is an outer corner  of $\lambda$, that is $\lambda\in X_{\alpha}$.
                                                                                                                                          
\item[{{\rm$($b$)$}}] $\lambda_{n+1-i} = j-1$ and $\lambda'_{j} = n-i$.
\end{itemize}
If these conditions hold then 
\begin{equation} \label{qhf} t_{\alpha}(\lambda) = (\lambda_1,\ldots , \lambda_{n-i}, \lambda_{n+1-i}+1,\lambda_{n+2-i},\ldots, \lambda_n).\end{equation}

