\label{ky} 
  Assume that   the following conditions holds.

                                                             
\begin{itemize} \item[{{\rm$($a$)$}}]
If $\beta\in \Delta_{1}^+$, $\lambda\in {\mathbb X}_{\beta}\cap  {\mathbb X}({\operatorname{r.full}})$ and 
${\lambda}^{-_\mathtt{r}} \in {\mathbb X}_{\nu\beta}$, then ${H(\rho_{\beta})(\lambda)}\in  {\mathbb X}({\operatorname{r.full}})$ and   
\begin{equation} \label{kz} ({H(\rho_{\beta})(\lambda)})^{-_\mathtt{r}} = H(\rho_{\nu\beta})({\lambda}^{-_\mathtt{r}}).\end{equation} 
\item[{{\rm$($b$)$}}]  
If $\beta\in \Delta_{1}^+$, $\lambda\in {\mathbb X}_{\beta}\cap  {\mathbb X}({\operatorname{c.full}})$ and 
${\lambda}^{-_\mathtt{c}} \in {\mathbb X}_{\eta\beta}$, then ${H(\rho_{\beta})(\lambda)}\in  {\mathbb X}({\operatorname{c.full}})$ and   
\begin{equation} \label{kz1} ({H(\rho_{\beta})(\lambda)})^{-_\mathtt{c}} = H(\rho_{\eta\beta})({\lambda}^{-_\mathtt{c}}).\end{equation} 

\end{itemize}

Assume Hypothesis \ref{ky} holds. \begin{itemize} \item[{{\rm$($a$)$}}]
If  $\beta\in \Delta_{1}^+$,  $\mu\in  {\mathbb X}_{-\nu\beta}\;\cap \in {\mathbb X}({\operatorname{r.empty}})$ and  ${\mu}^{+_\mathtt{r}} \in {\mathbb X}_{-\beta}$, then  ${H(\rho_{-\nu\beta})(\mu)}\in  {\mathbb X}({\operatorname{r.empty}})$ and  
\begin{equation} \label{kf} ({H(\rho_{-\nu\beta})(\mu)})^{+_\mathtt{r}} = H(\rho_{-\beta})({\mu}^{+_\mathtt{r}}).\end{equation}
\item[{{\rm$($b$)$}}]
If  $\beta\in \Delta_{1}^+$,  $\mu\in  {\mathbb X}_{-\eta\beta}\;\cap \in {\mathbb X}({\operatorname{c.empty}})$ and  ${\mu}^{+_\mathtt{c}} \in {\mathbb X}_{-\beta}$, then  ${H(\rho_{-\eta\beta})(\mu)}\in  {\mathbb X}({\operatorname{c.empty}})$ and  
\begin{equation} \label{kf1} ({H(\rho_{-\eta\beta})(\mu)})^{+_\mathtt{c}} = H(\rho_{-\beta})({\mu}^{+_\mathtt{c}}).\end{equation}
\end{itemize}

\label{186} {\rm 
The proof of Theorem \ref{185} shows more. The Cartan subalgebra $\mathfrak{h}$ appears in the definition of both $\widehat{L}(\stackrel{{\rm _o}}{\mathfrak{g}})$ and $\mathfrak{g}(A,\tau)$ and  the isomorphism is the identity on $\mathfrak{h}$. Also  the generators $e_0, e_1, \ldots, e_r$ and $f_0, f_1, \ldots, f_r$  of $\widehat{L}(\stackrel{{\rm _o}}{\mathfrak{g}})$ correspond under the isomorphism to the canonical generators of $\mathfrak{g}(A,\tau)$  as a  KM  Lie superalgebra. 
}

\label{glh}{\rm In Example \ref{glk} we carried out some computations with partitions (equivalently with words), indicating how to pass from  ${ \boldsymbol \lambda}$ to 
$\emptyset$  by deleting a row and a column and using a single odd reflection.  For convenience we recall some  details when $n=3,  m=4$.  Thus    ${\lambda= \boldsymbol \lambda}=\mathtt{r}^{}  \mathtt{d}^{2}\mathtt{r}^{3}\mathtt{d}^{}$, $\lambda^{-_\mathtt{r}}=\mathtt{d}^{}\mathtt{r}^{}  \mathtt{d}^{2}\mathtt{r}^{3}$ and  
$\mu=\mathtt{r}^{}  \mathtt{d}^{3}\mathtt{r}^{3}.$                                                                                                                                                            
Now by \eqref{1kr} 
$(\lambda,0)\sim (\lambda^{-_\mathtt{r}}, 4)$. Then using an odd reflection, we have 
$r_\alpha(\lambda^{-_\mathtt{r}},4)=(\mu, 4)$ 
and  by \eqref{2kr} 
$(\mu,4)\sim (\mu^{-_\mathtt{c}}, 7)= (\emptyset, 7)$.
                             
In the table we give the global names for the simple roots of the Borel subalgebras corresponding to the above calculation.    
}

\label{E4}{\rm We consider certain Borel subalgebras of $\widehat{L}(\stackrel{{\rm _o}}{\mathfrak{g}})$, when $\stackrel{{\rm o}}{\mathfrak{g}}=\mathfrak{sl}(2|3)$. 
                                             
Let $\sigma, \sigma_1$ be the shuffles with
$${ \boldsymbol \sigma}                             
= ( 1',1, 2',3', 2 ) \mbox{ and } { \boldsymbol \sigma}_1                                
= ( 1',2', 1, 3', 2).$$
Let $\mathfrak{b}(\sigma)$ and $\mathfrak{b}(\sigma_1)$ be the Borel subalgebras of ${\stackrel{{\rm o}}{\mathfrak{g}}}$ corresponding to $\sigma$ and $ \sigma_1$.  
Note that $\mathfrak{b}(\sigma)$ and $\mathfrak{b}(\sigma_1)$  are related by odd reflections using the roots
$\pm(\epsilon_1-\delta_2).$ We give two examples of the procedure defined above.  In the first
(resp. second) the Dynkin-Kac diagram for $\mathfrak{b}(\sigma)$ (resp.  $\mathfrak{b}(\sigma_1)$) is given on the left, the corresponding diagram for the affinization is in the middle and if $\tau$ (resp. $\tau_1$) is the shuffle obtained by the procedure, the Dynkin-Kac diagram for $\mathfrak{b}(\tau)$ (resp.  $\mathfrak{b}(\tau_1)$) is given on the  right.    
Note that $\mathfrak{b}(\tau)$ and $\mathfrak{b}(\tau_1)$  are related by odd reflections using the roots
$\pm(\epsilon_2-\delta_2).$

